package com.ecommerce.controller;
import com.ecommerce.dto.OrderDtos.*; import com.ecommerce.model.User; import com.ecommerce.service.*; import jakarta.validation.Valid; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/orders") public class OrderController { private final OrderService orders; private final UserLookupService users; public OrderController(OrderService orders,UserLookupService users){this.orders=orders;this.users=users;} @PostMapping("/checkout") public OrderResponse checkout(@Valid @RequestBody CheckoutRequest r,Authentication a){return orders.checkout(current(a),r);} @GetMapping public List<OrderResponse> myOrders(Authentication a){return orders.myOrders(current(a));} private User current(Authentication a){return users.currentUser(a);} }